# The sheet's rates, by grade then from-date, re-read from the store.
load:
  class: net.officefloor.hq.app.rate.LoadRates
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithRates
# Set the rate for a grade (A, B or C): a percent, 0.00 or more with up to two decimals, from an
# optional from-date (blank: from the beginning of time). Replaces the grade's rate from that date
# when it has one.
validate:
  class: net.officefloor.hq.app.rate.ValidateRate
  next: save
save:
  class: net.officefloor.hq.app.rate.SaveRate
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithRate
# Read the sheet's today, re-read from the store.
load:
  class: net.officefloor.hq.app.sheet.LoadSheetToday
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
# Change the sheet's today: the date every date decision and default date in the sheet uses.
validate:
  class: net.officefloor.hq.app.sheet.ValidateToday
  next: save
save:
  class: net.officefloor.hq.app.sheet.SaveSheetToday
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
