content.content:
-- A sheet: everything else in the app is kept per sheet, keyed by its id. A row is made the
-- first time an id is loaded; a sheet never loaded before starts empty.
CREATE TABLE sheet (
    id         VARCHAR(200) PRIMARY KEY,
    created_by VARCHAR(200) NOT NULL
);
-- The sheet's own "today": every date decision and default date in the sheet uses it, never the
-- real clock. A sheet starts on the real date it was made.
ALTER TABLE sheet ADD COLUMN today DATE DEFAULT CURRENT_DATE NOT NULL;
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet with this id, made empty (its today the real date) when the id was never used. */
    public Sheet loadOrCreate(String id, String user) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, id);
        if (known == null || known == 0) {
            try {
                jdbc.update("INSERT INTO sheet (id, created_by, today) VALUES (?, ?, ?)", id, user,
                        Date.valueOf(LocalDate.now()));
            } catch (DuplicateKeyException made) {
                // another user loaded the same new id at the same moment: it is made either way
            }
        }
        return new Sheet(id, today(id).toString());
    }

    /** The sheet's today: the date every date decision and default in the sheet uses. */
    public LocalDate today(String id) {
        Date today = jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", Date.class, id);
        return today.toLocalDate();
    }

    /** Set the sheet's today; false when there is no such sheet. */
    public boolean setToday(String id, LocalDate today) {
        return jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", Date.valueOf(today), id) > 0;
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { counts, fixedDue, useClaims } from '../claims/useClaims';
import { GRADES, heldIds, usePeople } from '../people/usePeople';
import { useSheetToday } from '../today/useSheetToday';
import { due, rateFor, ratesKey, sumDues, useRates, type Rate } from './useRates';

/** The sheet's rates for each grade: a form that sets one from an optional from-date (replacing the
 *  grade's rate from that date; blank is from the beginning of time), the rates set, and the rate in
 *  force on the sheet's today for every grade ('n/a' when none is). */
function Rates({ sheetId }: { sheetId: string }) {
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
